$c=Get-Content 'C:\email\emails.js' -Raw; $k=[regex]::Match($c,'x-functions-key:\s*([A-Za-z0-9_\-=]+)').Groups[1].Value; $u=[regex]::Match($c,'https://[A-Za-z0-9\-\.]+\.azurewebsites\.net/runtime/webhooks/mcp').Value; "URLLEN=" + $u.Length; "URLCODES=" + (($u.ToCharArray()|ForEach-Object{[int]$_}) -join ' '); "KEYLEN=" + $k.Length; "KEYCODES=" + (($k.ToCharArray()|ForEach-Object{[int]$_}) -join ' '); "DONE"
